// Extended coastal buffer — 0.65° (~70km) to better catch offshore grid cells
// in the Celtic Sea, North of Ireland, and West of Scotland sea areas.
// 0.35° (~39 km) coastal buffer — enough to include offshore grid cells along
// the UK/Irish coast without reaching the continental European coast, which is
// only ~40 km from the UK's east coast at the Dover strait.
const COASTAL_BUFFER_DEG = 0.35;

function pointInRingRaw(lon, lat, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1];
    const xj = ring[j][0], yj = ring[j][1];
    const intersect = ((yi > lat) !== (yj > lat))
      && (lon < (xj - xi) * (lat - yi) / ((yj - yi) || 1e-12) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function distToSegment(lon, lat, a, b) {
  const dx = b[0] - a[0], dy = b[1] - a[1];
  const len2 = dx * dx + dy * dy;
  if (len2 < 1e-12) {
    const ex = lon - a[0], ey = lat - a[1];
    return Math.sqrt(ex * ex + ey * ey);
  }
  let t = ((lon - a[0]) * dx + (lat - a[1]) * dy) / len2;
  t = Math.max(0, Math.min(1, t));
  const px = a[0] + t * dx, py = a[1] + t * dy;
  return Math.sqrt((lon - px) ** 2 + (lat - py) ** 2);
}

function distToRing(lon, lat, ring) {
  let best = Infinity;
  for (let i = 0; i < ring.length; i++) {
    const d = distToSegment(lon, lat, ring[i], ring[(i + 1) % ring.length]);
    if (d < best) best = d;
  }
  return best;
}

// ── Data-plot box ────────────────────────────────────────────────────────────
// The rectangular UK & Ireland region the model PROCESSES and PLOTS into. Wider
// than the ragged coastline mask (so the box is filled, incl. the surrounding
// seas), and kept in step with the box drawn on the maps. One source of truth.
export const UK_IE_DATA_BOX = { latMin: 49.8, latMax: 61.2, lonMin: -11.0, lonMax: 2.2 };
export function isInDataBox(lat, lon) {
  return lat >= UK_IE_DATA_BOX.latMin && lat <= UK_IE_DATA_BOX.latMax
      && lon >= UK_IE_DATA_BOX.lonMin && lon <= UK_IE_DATA_BOX.lonMax;
}

export function isInUKIreland(lat, lon) {
  // Extended bbox: full Celtic Sea, West of Scotland, North of Ireland, AND the
  // English Channel out to the northern France coastal strip (Dunkirk in the
  // east, down to the Seine/Le Havre approaches in the south). lonMax raised to
  // 2.7°E to admit the Dunkirk/Calais hinterland; latMin lowered to 49.3°N for
  // the Le Havre / Seine-mouth southern limit; 49.1°N also admits Jersey.
  if (lat < 49.1 || lat > 61.2) return false;
  if (lon < -16.0 || lon > 2.7) return false;

  // ── Channel Islands (Jersey, Guernsey, Alderney, Sark) ───────────────────
  // A small detached group in the Gulf of St-Malo, south of the main Channel
  // loop. Included explicitly as a compact box so they paint without having to
  // distort the GB polygon south toward the French (Cotentin/Brittany) coast.
  if (lat >= 49.10 && lat <= 49.75 && lon >= -2.75 && lon <= -1.85) return true;

  // ── Deep-France exclusions ───────────────────────────────────────────────
  // The GB loop deliberately includes a ~50 km northern-France coastal strip,
  // but a few inland/peninsula spots sit just inside that loop and should be
  // cut so risk doesn't bleed into Normandy, Picardy interior or the Paris
  // basin:
  //   • Cotentin peninsula (Cherbourg/Caen) — west of the Seine, sticks north.
  //   • Lower Seine interior (Rouen) — deeper than the intended strip.
  //   • Picardy interior (Amiens) — deeper than the intended strip.
  if (lat < 49.95 && lon >= -1.95 && lon <= -0.30) return false;  // Cotentin / Caen
  if (lat < 49.60 && lon >= 0.70 && lon <= 1.45) return false;    // Rouen interior
  if (lat < 50.20 && lon >= 1.95 && lon <= 2.70) return false;    // Picardy interior (Amiens)

  // ── Irish Sea ────────────────────────────────────────────────────────────
  // The central Irish Sea between the Irish east coast (~-6°W) and the Welsh /
  // NW-England west coast (~-4.5°W) is wholly UK/Irish water but falls in the
  // ~0.5° dead zone between the two polygons' coastal buffers. Fill it so the
  // forecast is continuous across the Irish Sea (as the reference coverage
  // shows) rather than leaving a seam down the middle.
  if (lat >= 51.6 && lat <= 55.0 && lon >= -6.2 && lon <= -3.0) return true;

  // ── Celtic Sea / South-Western Approaches ────────────────────────────────
  // The sea SW of Cornwall and S of Ireland (the Celtic Sea) sits between the
  // GB polygon's Cornwall segment and Ireland's south coast, leaving a gap
  // around 50.6–51.5°N / -6.5–-5.0°W. It is entirely UK/Irish water and is
  // shown covered in the reference, so fill it for continuous coverage.
  if (lat >= 49.8 && lat <= 51.6 && lon >= -7.5 && lon <= -4.8) return true;

  // ── Atlantic — West of Scotland & North of Ireland ───────────────────────
  // Open ocean wedge west of the Hebrides and north of Donegal/Malin Head,
  // out to ~-16°W. This is the Atlantic approaches where Atlantic convection
  // and frontal storms first reach the British Isles, so the model should
  // extend into it. North of Ireland: 54.5–58.5°N. West of Scotland: the box
  // reaches up to the Faroe-Shetland gap latitudes.
  if (lat >= 54.5 && lat <= 60.5 && lon >= -16.0 && lon <= -7.0) return true;
  // North-Irish / Donegal Atlantic approaches (slightly further south).
  if (lat >= 53.5 && lat <= 56.5 && lon >= -16.0 && lon <= -9.5) return true;

  if (pointInRingRaw(lon, lat, GB_POLY)) return true;
  if (pointInRingRaw(lon, lat, IRELAND_POLY)) return true;

  // Coastal buffer for offshore grid cells. Skip the buffer near the eastern
  // bbox limit so it can't reach past 2.7°E onto the Belgian coast.
  if (lon <= 2.45) {
    if (distToRing(lon, lat, GB_POLY) <= COASTAL_BUFFER_DEG) return true;
  }
  if (distToRing(lon, lat, IRELAND_POLY) <= COASTAL_BUFFER_DEG) return true;

  return false;
}

export function clipGridToUKIreland(grid) {
  return grid.filter(p => isInUKIreland(p.lat, p.lon));
}

function findBoundaryCrossing(insidePt, outsidePt) {
  let aLon = insidePt[0], aLat = insidePt[1];
  let bLon = outsidePt[0], bLat = outsidePt[1];
  for (let i = 0; i < 14; i++) {
    const mLon = (aLon + bLon) / 2;
    const mLat = (aLat + bLat) / 2;
    if (isInUKIreland(mLat, mLon)) {
      aLon = mLon; aLat = mLat;
    } else {
      bLon = mLon; bLat = mLat;
    }
  }
  return [aLon, aLat];
}

export function clipRingToUKIreland(ring) {
  if (!ring || ring.length < 3) return [];

  const n = ring.length;
  const inside = new Array(n);
  for (let i = 0; i < n; i++) {
    inside[i] = isInUKIreland(ring[i][1], ring[i][0]);
  }

  let allIn = true, allOut = true;
  for (let i = 0; i < n; i++) {
    if (inside[i]) allOut = false; else allIn = false;
    if (!allIn && !allOut) break;
  }
  if (allIn) return [ring.slice()];
  if (allOut) return [];

  // Find a safe starting index: an outside→inside transition.
  // Starting from index 0 when it's inside means the first sub-ring
  // has no entry crossing and won't be closed correctly on wrap-around.
  let startIdx = 0;
  for (let i = 0; i < n; i++) {
    if (!inside[i] && inside[(i + 1) % n]) {
      startIdx = i;
      break;
    }
  }

  const subRings = [];
  let cur = null;

  for (let step = 0; step < n; step++) {
    const i = (startIdx + step) % n;
    const a = ring[i];
    const b = ring[(i + 1) % n];
    const aIn = inside[i];
    const bIn = inside[(i + 1) % n];

    if (aIn) {
      if (!cur) cur = [];
      cur.push(a);
      if (!bIn) {
        // exiting — add boundary crossing and close the sub-ring
        cur.push(findBoundaryCrossing(a, b));
        if (cur.length >= 3) subRings.push(cur);
        cur = null;
      }
    } else if (bIn) {
      // entering — start a new sub-ring from the boundary crossing
      cur = [findBoundaryCrossing(b, a)];
    }
  }
  // Close any open sub-ring (ring ended while still inside)
  if (cur && cur.length >= 3) subRings.push(cur);

  return subRings;
}

